import { database } from '../services/local';
import { Draft } from '../services/local-schema';

export async function persistDraft(input: unknown) {
  const draft = Draft.parse(input);
  const db = await database();
  await db.runAsync(
    'INSERT OR REPLACE INTO drafts(owner,id,value) VALUES (?,?,?)',
    draft.owner, draft.id, JSON.stringify(draft),
  );
}

export async function readDrafts(owner: string) {
  const db = await database();
  const rows = await db.getAllAsync<{ value: string }>(
    'SELECT value FROM drafts WHERE owner = ?', owner,
  );
  return rows.map(row => Draft.parse(JSON.parse(row.value)));
}

const saved = new Map<string, { nickname: string }>();
const operationKey = 'plant_draft_42';
const frozenPayload = { nickname: 'Trail maple' };

async function serverSave(key: string, payload: { nickname: string }) {
  const previous = saved.get(key);
  if (previous) {
    if (previous.nickname !== payload.nickname) throw new Error('Conflict');
    return previous;
  }
  const result = { ...payload };
  saved.set(key, result);
  return result;
}

export async function clientAttempt(loseAcknowledgement: boolean) {
  const result = await serverSave(operationKey, frozenPayload);
  if (loseAcknowledgement) throw new Error('Reply was lost after commit');
  return { result, serverRecordCount: saved.size };
}
// await clientAttempt(true) rejects after the server has saved.
// await clientAttempt(false) returns the same result and count 1.
